import logo from './logo.svg';
import './App.css';
import styles from './styles/InputStyles.module.css';

function App() {
  //return SubmitProblem();
  const [textValue, setTextValue] = useState('');
  const handleSubmit = () => {
    const descriptionInput = document.getElementById('description');
    const descriptionText = descriptionInput.value;
    if (descriptionText.trim() === '') {
      alert('题目描述不能为空');
    }else{
      console.log('题目描述：',descriptionText);
      alert('题目描述已提交:')
    }
  };
  return (
    <div className="App">
        <div>
          <h1>Submit Problem</h1>
        </div>
        <div>
          <label for="description">题目描述:</label>
          <textarea value={textValue} onChange={(e) => setTextValue(e.target.value)} rows="10" cols="50" id="description" name = "description"></textarea>
          <input type="text" id="description" name = "description" class = {styles.largeTextarea}></input>
        </div>
        <div>
          <button id="submitBtn" onClick={handleSubmit}>提交</button>
        </div>
    </div>
  );
}

export default App;
